// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the `from` address and an uint value; we will always use a single recipient
    // The adversarial callee will revert when called, causing the reference to revert
    // but the mutant (which ignores the success flag) will not revert and will return true.
    function testFuzz_property(address from, uint256 v) public {
        // keep wide but avoid the zero-address for the recipient deployment sanity (not strictly needed)
        vm.assume(from != address(0));

        // deploy a callee that always reverts when transferFrom is invoked
        Reverter rev = new Reverter();

        // prepare a single-element array of recipients; we need memory array
        address[] memory tos = new address[](1);
        tos[0] = address(rev);

        bool ok;
        // call c.transfer and observe whether it reverts. Reference SHOULD revert (ok==false)
        try c.transfer(from, address(rev), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ALL admissible inputs, the reference contract reverts when the callee reverts.
        // Thus ok must be false. The buggy mutant (which removes require(_s)) will return true (ok==true)
        assertTrue(!ok);
    }
}

// adversarial callee that exposes the exact selector transferFrom(address,address,uint256)
// and always reverts when called, to distinguish behaviour between checking the success flag
contract Reverter {
    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address, address, uint256) external pure {
        revert("revert-from-callee");
    }
}
